package com.huawei.oss.wireless.experienceassuranceservice.common.impl.utils;

import com.huawei.bsp.log.OssLog;
import com.huawei.bsp.log.OssLogFactory;
import com.huawei.bsp.remoteservice.exception.ServiceException;
import com.huawei.maos.commons.deploy.EnvUtil;
import com.huawei.maos.commons.text.StringUtil;
import com.huawei.oss.rest.util.RestCaller;
import com.huawei.oss.rest.util.RestMethod;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * 实例工具类
 *
 * @since 2025/07/25
 */
public class InstanceUtils {
    private static final OssLog LOGGER = OssLogFactory.getLogger(InstanceUtils.class);

    private static final String INSTANCE_ONLY_POLICY = "instanceOnly";

    private static final String BACKEND_LIST_POLICY_HEADER = "XX-Backend-List-Policy";

    private static final String BACKEND_LIST_HEADER = "Xx-Backend-List";

    private static final String ALL_INSTANCES_PREFIX = "all=";

    private static final String POD_NAME_ENV = "POD_NAME";

    private static final String INSTANCE_ID_SEPARATOR = ",";

    private static final String INSTANCE_NAME_SEPARATOR = "-";

    private static final String POLICY_URL = "/rest/oss/inner/experienceassurance/v1/policy";

    /**
     * 查询所有实例ID
     *
     * @return 所有实例ID列表
     */
    public static List<Integer> queryAllInstanceIds() {
        try {
            String backendList = getBackendList();
            if (!StringUtil.isNullOrEmpty(backendList)
                && backendList.startsWith(ALL_INSTANCES_PREFIX)) {
                String instancesStr = backendList.substring(ALL_INSTANCES_PREFIX.length());
                String[] instances = instancesStr.split(INSTANCE_ID_SEPARATOR);
                List<Integer> instanceIds = new ArrayList<>();
                for (String instance : instances) {
                    String trimmed = instance.trim();
                    if (StringUtil.isNullOrEmpty(trimmed)) {
                        continue;
                    }
                    Optional<Integer> instanceId = parseInstanceId(trimmed);
                    instanceId.ifPresent(instanceIds::add);
                }
                return instanceIds;
            }
            return new ArrayList<>();
        } catch (ServiceException e) {
            LOGGER.error("queryAllInstanceIds failed.", e);
            return new ArrayList<>();
        } catch (Exception e) {
            LOGGER.error("queryAllInstanceIds unexpected error.", e);
            return new ArrayList<>();
        }
    }

    /**
     * 查询当前实例ID
     *
     * @return 当前实例ID
     */
    public static Optional<Integer> queryCurrentInstanceId() {
        try {
            String podName = EnvUtil.getEnv(POD_NAME_ENV);
            if (StringUtil.isNullOrEmpty(podName)) {
                return Optional.empty();
            }
            return parseInstanceId(podName.trim());
        } catch (Exception e) {
            LOGGER.error("queryCurrentInstanceId failed.", e);
            return Optional.empty();
        }
    }

    /**
     * 从响应头中获取Backend List值（不区分大小写查找）
     *
     * @return Backend List值
     * @throws ServiceException 服务异常
     */
    private static String getBackendList() throws ServiceException {
        Map<String, List<String>> respHeaderMap = RestCaller.builder()
            .url(POLICY_URL)
            .method(RestMethod.POST)
            .addHeader(BACKEND_LIST_POLICY_HEADER, INSTANCE_ONLY_POLICY)
            .call()
            .getHeaderMap();
        for (Map.Entry<String, List<String>> entry : respHeaderMap.entrySet()) {
            if (entry.getKey().equalsIgnoreCase(BACKEND_LIST_HEADER)) {
                List<String> values = entry.getValue();
                if (values != null && !values.isEmpty()) {
                    return values.get(0);
                }
            }
        }
        return null;
    }

    private static Optional<Integer> parseInstanceId(String instanceName) {
        try {
            if (StringUtil.isNullOrEmpty(instanceName)) {
                return Optional.empty();
            }
            String[] parts = instanceName.split(INSTANCE_NAME_SEPARATOR);
            if (parts.length == 0) {
                return Optional.empty();
            }
            String lastPart = parts[parts.length - 1];
            if (StringUtil.isNullOrEmpty(lastPart)) {
                return Optional.empty();
            }
            int id = Integer.parseInt(lastPart);
            return Optional.of(id);
        } catch (NumberFormatException e) {
            return Optional.empty();
        }
    }
}
